import sys
from functools import lru_cache

data = sys.stdin.read().split()
w = int(data[0])
words = data[1:1 + w]
target = data[1 + w]
MOD = 1000000007
L = len(words[0])
T = len(target)

@lru_cache(None)
def g(p, c):
    if p == T:
        return 1
    total = 0
    for col in range(c, L):
        for word in words:
            if word[col] == target[p]:
                total += g(p + 1, col + 1)
    return total % MOD

print(g(0, 0) % MOD)

